//! Upstream JS data embedded as JSON: the provider registry, model tables
//! and constants from open-sse/config, open-sse/providers,
//! open-sse/translator/schema and src/shared/constants.
//!
//! `data/` is generated by `tools/dump-js-data.mjs` (re-run it after merging
//! upstream). Each file is `{ "source", "exports", "functions" }`;
//! `functions` lists the JS functions that could not be dumped — their Rust
//! ports live in this crate's modules.

use std::collections::HashMap;
use std::sync::LazyLock;

use nr_core::{Json, JsonMap};

include!(concat!(env!("OUT_DIR"), "/files.rs"));

static MODULES: LazyLock<HashMap<&'static str, Json>> = LazyLock::new(|| {
    FILES
        .iter()
        .map(|(key, text)| (*key, serde_json::from_str(text).unwrap_or_else(|e| panic!("nr-data: bad JSON in {key}: {e}"))))
        .collect()
});

static EMPTY_MAP: LazyLock<JsonMap> = LazyLock::new(JsonMap::new);

/// The whole dump of one JS module, keyed by its path without extension,
/// e.g. `"open-sse/config/runtimeConfig"`.
pub fn module(path: &str) -> Option<&'static Json> {
    MODULES.get(path)
}

/// One named export of a JS module, e.g. `export("open-sse/config/runtimeConfig", "HTTP_STATUS")`.
pub fn export(path: &str, name: &str) -> Option<&'static Json> {
    module(path)?.get("exports")?.get(name)
}

/// Names of every embedded module.
pub fn module_names() -> impl Iterator<Item = &'static str> {
    FILES.iter().map(|(k, _)| *k)
}

fn export_map(path: &str, name: &str) -> &'static JsonMap {
    export(path, name).and_then(Json::as_object).unwrap_or(&EMPTY_MAP)
}

/// `PROVIDERS` (open-sse/providers/index.js): transport config per provider id.
pub fn providers() -> &'static JsonMap {
    export_map("open-sse/providers/index", "PROVIDERS")
}

pub fn provider(id: &str) -> Option<&'static Json> {
    providers().get(id)
}

/// `PROVIDER_MODELS`: model lists keyed by provider alias (or id).
pub fn provider_models() -> &'static JsonMap {
    export_map("open-sse/providers/index", "PROVIDER_MODELS")
}

/// `PROVIDER_OAUTH`: OAuth config per provider id.
pub fn provider_oauth(id: &str) -> Option<&'static Json> {
    export_map("open-sse/providers/index", "PROVIDER_OAUTH").get(id)
}

/// `PROVIDER_MEDIA`: media (tts/stt/embedding/image/…) config per provider id.
pub fn provider_media(id: &str) -> Option<&'static Json> {
    export_map("open-sse/providers/index", "PROVIDER_MEDIA").get(id)
}

/// Raw registry entries (open-sse/providers/registry/*.js), including `display`.
pub fn registry() -> &'static [Json] {
    export("open-sse/providers/registry/index", "default").and_then(Json::as_array).map(Vec::as_slice).unwrap_or(&[])
}

pub fn registry_entry(id: &str) -> Option<&'static Json> {
    registry().iter().find(|e| e.get("id").and_then(Json::as_str) == Some(id))
}

/// A constant from open-sse/config/runtimeConfig.js, e.g. `runtime("FETCH_CONNECT_TIMEOUT_MS")`.
pub fn runtime(name: &str) -> Option<&'static Json> {
    export("open-sse/config/runtimeConfig", name)
}

/// Numeric runtime constant; panics if missing, since that means the dump is stale.
pub fn runtime_u64(name: &str) -> u64 {
    runtime(name).and_then(Json::as_u64).unwrap_or_else(|| panic!("nr-data: runtimeConfig.{name} missing; re-run tools/dump-js-data.mjs"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn data_is_embedded() {
        assert!(registry().len() > 100, "registry has {} entries", registry().len());
        assert!(provider("openai").is_some());
        assert_eq!(runtime_u64("FETCH_CONNECT_TIMEOUT_MS"), 60_000);
        assert!(export("open-sse/translator/schema/roles", "ROLE").is_some());
        assert!(registry_entry("zed").is_some());
    }
}
